import React from "react";
import { sidebarLinks } from "../../../data/dashboard-links";
import { NavLink } from "react-router-dom";
import { useSelector } from "react-redux";
import { useLocation } from "react-router-dom";
import * as Icons from 'react-icons/vsc';
import { IoSettingsOutline } from "react-icons/io5";
import { PiSignOut } from "react-icons/pi";

const Sidebar = ({ setshowModal }) => {
  const { user } = useSelector((state) => state.profile);
  const location = useLocation();

  return (
    <div className="fixed left-0 top-0 h-screen">
      <div className="flex flex-col gap-5 h-full bg-richblack-700 text-richblack-300 w-36 lg:w-40 xl:w-52 pt-4">
        <div className="flex flex-col py-3 gap-4 transition-all duration-200">
          {sidebarLinks.map((link, index) => {
            const Icon = Icons[link.icon];
            if (!link.type) {
              return (
                <NavLink key={index} to={link.path}>
                  <div className={`flex items-center justify-start gap-3 px-4 py-2 border-l-[3px] ${location.pathname === link.path ? 'bg-yellow-50 bg-opacity-20 border-l-yellow-200' : 'border-l-transparent'}`}>
                    <Icon className={`text-xl ${location.pathname === link.path && 'text-yellow-100'}`} />
                    <p>{link.name}</p>
                  </div>
                </NavLink>
              );
            }

            if (user && link.type === user?.accountType) {
              return (
                <NavLink key={index} to={link.path}>
                  <div className={`flex items-center justify-start gap-3 px-4 py-2 border-l-[3px] ${location.pathname === link.path ? 'bg-yellow-50 bg-opacity-20 border-l-yellow-200' : 'border-l-transparent'}`}>
                    <Icon className={`text-xl ${location.pathname === link.path && 'text-yellow-100'}`} />
                    <p>{link.name}</p>
                  </div>
                </NavLink>
              );
            }

            return null;
          })}
        </div>

        <div className="h-[1px] bg-richblack-500"></div>

        <div className="flex flex-col gap-4">
          <NavLink to={'/dashboard/settings'}>
            <div className={`flex items-center justify-start gap-4 px-4 py-2 border-l-[3px] ${location.pathname === '/dashboard/settings' ? 'bg-yellow-50 bg-opacity-20 border-l-yellow-200' : 'border-l-transparent'}`}>
              <IoSettingsOutline className={`text-xl ${location.pathname === '/dashboard/settings' && 'text-yellow-100'}`} />
              <p>Settings</p>
            </div>
          </NavLink>

          <div
            className="cursor-pointer group flex items-center justify-start gap-4 px-4 py-2"
            onClick={() => setshowModal(true)}
          >
            <PiSignOut className="text-xl group-hover:text-yellow-100" />
            <p className="group-hover:text-yellow-100">LogOut</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
